index 1a2b3c4..5d6e7f8 100644
--- a/web/reports/export.ts
+++ b/web/reports/export.ts
@@ -31,8 +31,12 @@
   context line
-export async function buildCsv(report: Report): Promise<string> {
-  const rows = await fetchRows(report.id);
-  const lines = rows.map((row) => toLine(report.columns, row));
-  return [header(report.columns), ...lines].join("\n");
-}
+export async function* streamCsv(report: Report, pageSize = 1000): AsyncGenerator<string> {
+  yield header(report.columns) + "\n";
+  for (let cursor: string | null = null; ; ) {
+    const page = await fetchRows(report.id, { cursor, limit: pageSize });
+    for (const row of page.rows) yield toLine(report.columns, row) + "\n";
+    if (!page.next) return;
+    cursor = page.next;
+  }
+}
