-def rows(report_id: str):
-    return list(db.report_rows(report_id))
+def rows(report_id: str, cursor: str | None = None, limit: int = 1000):
+    page = db.report_rows(report_id, after=cursor, limit=limit + 1)
+    return {"rows": page[:limit], "next": page[limit - 1].id if len(page) > limit else None}
